#include "bench.h"
/* Sort 64 generated bytes, then compute an order-sensitive checksum. */
unsigned short bench_run(unsigned short seed)
{
    unsigned char data[64], value;
    unsigned short state, checksum;
    int i, j;
    state = seed;
    for (i = 0; i < 64; ++i) {
        state = (unsigned short)((unsigned long)state * 109UL + 89UL);
        data[i] = (unsigned char)(state >> 8);
    }
    for (i = 1; i < 64; ++i) {
        value = data[i];
        j = i;
        while (j > 0 && data[j - 1] > value) {
            data[j] = data[j - 1];
            --j;
        }
        data[j] = value;
    }
    checksum = 0;
    for (i = 0; i < 64; ++i)
        checksum = (unsigned short)((unsigned long)checksum * 3UL + data[i]);
    return checksum;
}
